CREATE FUNCTION func_minimum(arr numeric[]) RETURNS numeric AS $$
    SELECT MIN(a) FROM unnest(arr) AS a;
$$ LANGUAGE sql;

CREATE FUNCTION func_minimum(VARIADIC nums numeric[]) RETURNS numeric AS $$
    SELECT MIN(a) FROM unnest(nums) AS a;
$$ LANGUAGE sql;
